DELIMITER $$
CREATE TRIGGER `update_block_apartment_count` AFTER INSERT ON `apartments` FOR EACH ROW BEGIN
    UPDATE blocks 
    SET total_apartments = (
        SELECT COUNT(*) FROM apartments WHERE block_id = NEW.block_id
    )
    WHERE id = NEW.block_id;
    
    UPDATE projects 
    SET total_apartments = (
        SELECT COUNT(*) FROM apartments a 
        JOIN blocks b ON a.block_id = b.id 
        WHERE b.project_id = 1
    )
    WHERE id = 1;
END
$$
